From f8a3fe33c34c8731fd2f02e582e907182621ccd6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:46:27 +0100
Subject: [PATCH] libs/editor: Save the hotspot password to disk right away

The hotspot password, like the random default one, was only written to
disk when the process that set it quit, so the Networks widget kept
using the old one. Sync it right away, as the hotspot name already does.

BUG: 469887
---
 libs/editor/configuration.cpp | 2 ++
 1 file changed, 2 insertions(+)

diff --git a/libs/editor/configuration.cpp b/libs/editor/configuration.cpp
index 79c794d74..0e93ae87f 100644
--- a/libs/editor/configuration.cpp
+++ b/libs/editor/configuration.cpp
@@ -147,6 +147,7 @@ QString Configuration::hotspotPassword() const
                 pwd += QString::number(QRandomGenerator::global()->bounded(base16), base16).toUpper();
             }
             grp.writeEntry(QStringLiteral("HotspotPassword"), pwd, KConfigBase::Notify);
+            grp.sync();
         }
         return pwd;
     }
@@ -161,6 +162,7 @@ void Configuration::setHotspotPassword(const QString &password)

     if (grp.isValid()) {
         grp.writeEntry(QStringLiteral("HotspotPassword"), password, KConfigBase::Notify);
+        grp.sync();
     }
 }

